export function normalizeDrugSearch(text: string) { return text.normalize("NFD").replace(/\p{Diacritic}/gu, "").toLowerCase().trim(); }
export function searchPracticeDrugs(query: string) {
 const words = normalizeDrugSearch(query).split(/\s+/).filter(Boolean);
 return PRACTICE_DRUGS.filter(d => words.every(word => normalizeDrugSearch([d.name, d.family, ...d.aliases, ...d.forms.flatMap(f => [f.route, f.label])].join(" ")).includes(word)));
}
export function drawMedicationChallenge(difficulty: ChallengeDifficulty, seen: string[], random = Math.random): MedicationChallenge {
 const pool = MEDICATION_CHALLENGES.filter(c => c.difficulty === difficulty);
 const fresh = pool.filter(c => !seen.includes(c.id));
 const available = fresh.length ? fresh : pool.filter(c => c.id !== seen.at(-1));
 const choices = available.length ? available : pool;
 const value = random();
 const index = Number.isFinite(value) ? Math.max(0, Math.min(choices.length - 1, Math.floor(value * choices.length))) : 0;
 return choices[index];
}
export function formatDose(value: number, unit: DoseUnit) { return `${new Intl.NumberFormat("es-EC", {maximumFractionDigits: 3}).format(value)} ${unit}`; }
export function dosePreparation(form: PracticeForm, dose: number): string | null {
 if (!form.strength || !form.measure || !Number.isFinite(dose) || dose <= 0) return null;
 const quantity = dose / form.strength;
 // Capsules and inhaler actuations cannot be split. Tablet splitting is reviewed separately.
 if ((form.measure === "cápsulas" || form.measure === "pulsaciones") && Math.abs(quantity - Math.round(quantity)) > 0.000001) return null;
 const singular: Record<string, string> = {comprimidos: "comprimido", cápsulas: "cápsula", pulsaciones: "pulsación", envases: "envase"};
 const measure = Math.abs(quantity - 1) < 0.000001 ? singular[form.measure] ?? form.measure : form.measure;
 return `${new Intl.NumberFormat("es-EC", {maximumFractionDigits: 3}).format(quantity)} ${measure}`;
}
export type ChallengeInput = { decision: "administer" | "hold"; drugId?: string; formId?: string; dose?: number; unit?: DoseUnit };
export type ChallengeResult = { appropriate: boolean; score: number; heading: string; detail: string; chosen: string; expected: string; followUp: string; checks: {medication: boolean; route: boolean; dose: boolean} | null };
export function evaluateMedicationChallenge(caseId: string, input: ChallengeInput): ChallengeResult | null {
 const c = MEDICATION_CHALLENGES.find(c => c.id === caseId);
 if (!c || (input.decision !== "hold" && input.decision !== "administer")) return null;
 const d = PRACTICE_DRUGS.find(d => d.id === input.drugId);
 const form = d?.forms.find(f => f.id === input.formId);
 if (input.decision === "administer" && (!d || !form || typeof input.dose !== "number" || !Number.isFinite(input.dose) || input.dose <= 0 || input.unit !== form.unit || !form.doses.includes(input.dose))) return null;
 const medication = c.accepted.some(a => a.drugId === d?.id);
 const route = c.accepted.some(a => a.drugId === d?.id && a.route === form?.route);
 const dose = c.accepted.some(a => a.drugId === d?.id && a.route === form?.route && (!a.formIds || a.formIds.includes(form!.id)) && a.unit === input.unit && a.doses.includes(input.dose!));
 const appropriate = input.decision === c.decision && (input.decision === "hold" || dose);
 const preparation = form && input.dose ? dosePreparation(form, input.dose) : null;
 const expected = c.decision === "hold" ? "Retener el tratamiento y solicitar revisión de la orden" : c.accepted.map(a => `${PRACTICE_DRUGS.find(d => d.id === a.drugId)?.name} · ${a.route} · ${a.doses.map(v => formatDose(v, a.unit)).join(" o ")}${a.formIds ? ` (${a.formIds.map(id => PRACTICE_DRUGS.find(d => d.id === a.drugId)?.forms.find(f => f.id === id)?.label).join(" / ")})` : ""}`).join(" / ");
 return {
  appropriate, score: appropriate ? 100 : input.decision === "administer" && c.decision === "administer" ? (medication ? route ? 60 : 30 : 0) : 0,
  heading: appropriate ? "Buena decisión para este caso" : "Una decisión para revisar", detail: c.rationale,
  chosen: input.decision === "hold" ? "Retener y consultar antes de administrar" : `${d!.name} · ${form!.label} · vía ${form!.route} · dosis total ${formatDose(input.dose!, form!.unit)}${preparation ? ` · ${preparation}` : ""}`,
  expected, followUp: c.followUp, checks: input.decision === "administer" ? {medication, route, dose} : null,
 };
}
